//! Oracle tier: reads artifacts regenerated by `scripts/regen-fixtures.py`
//! (tools/fixtures/langlibelk-language-{public,url}.toml, docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_language::compiler::import_urls;
use serde_json::Value;
#[test]
fn pinned_go_url_diagnostics_and_reachable_predicates() {
    let fixture: Value = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/public-url-validation-v090.json"
    ))
    .unwrap();
    let requests = fixture["requests"].as_array().unwrap();
    let source = fixture["source"].as_array().unwrap();
    assert!(!requests.is_empty());
    assert_eq!(requests.len(), source.len());
    for (request, expected) in requests.iter().zip(source) {
        let hex = request["hex"].as_str().unwrap();
        let input = (0..hex.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
            .collect::<Vec<_>>();
        let actual = match import_urls::parse(&input, request["request"].as_bool().unwrap()) {
            Ok(parsed) => serde_json::json!({"remote":parsed.remote,"has_host":parsed.has_host}),
            Err(error) => serde_json::json!({"error":error}),
        };
        assert_eq!(&actual, expected, "{request}");
    }
}
